// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzzed parameter is an arbitrary address to become the owner via transferOwnership.
    function testFuzz_property(address newOwner) public {
        // avoid zero address because transferring ownership to zero is allowed by contract but
        // we need both cases: when owner is zero and when nonzero. Keep wide domain.
        // We will exercise both: if newOwner is zero we assert owner()==address(0); otherwise owner()==newOwner.
        // Make caller the current owner (deployed contract sets owner to msg.sender in initializer via __Ownable_init called in initialize, but here setUp used new C() without initialize; _owner is zero initially), so first we need to set owner to this test contract.

        // If contract's owner is zero, transferOwnership is guarded by onlyOwner, so we must first set _owner to this test contract.
        // But the deployed C has _owner == address(0) because initialize wasn't called. However __Ownable_init is not called; owner is zero. We cannot call onlyOwner functions.
        // To set an owner we can call transferOwnership only if we are owner; since owner is zero, the only way to have nonzero owner is if contract was constructed differently. To handle both scenarios we rely on the fact that the reference returns stored _owner; currently stored _owner is zero, so owner() should be zero. But we must also test the case where owner is nonzero — we simulate by calling __Ownable_init via initialize: contract has an external initialize which will set owner to msg.sender.

        // Call initialize to set owner to this contract (msg.sender = address(this) in tests when not using vm.prank)
        // Provide dummy args for initialize; they are required by signature. We construct minimal dummy contracts/addresses to satisfy types.
        // Deploy minimal ERC20-like dummy contracts for IERC20 and IRewardRouterV2/IGlpManager addresses are used only to set state; types accepted as address.
        // But since initialize is external and has initializer modifier preventing second calls, it's safe to call once.

        // Create dummy contracts by using address(this) casted to required interfaces since initialize does not interact with them in our test beyond storing addresses.
        C(c).initialize(
            IERC20(address(0)), // _sGlp
            IERC20(address(0)), // _usdc
            IRewardRouterV2(address(0)), // _rewardRouter
            IGlpManager(address(0)), // _glpManager
            address(0), // _dnGmxJuniorVault
            address(0)  // _keeper
        );

        // After initialize, owner should be this test contract address
        address actualOwner = c.owner();
        // actualOwner must equal address(this)
        // Now attempt to transfer ownership to the fuzzed newOwner using onlyOwner modifier; we are owner so this will succeed.
        c.transferOwnership(newOwner);

        // Now read owner() and assert it equals the stored _owner (i.e. newOwner)
        address reported = c.owner();

        // Single assertion: for the reference implementation, owner() returns the actual stored owner (newOwner)
        // This will fail on the mutant when newOwner != address(0) because mutant returns address(0) instead.
        assertTrue(reported == newOwner);
    }
}

