pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed param: an address newOwner to set as owner (must be allowed by transferOwnership)
    function testFuzz_property(address newOwner) public {
        // Keep domain wide but avoid zero because transferOwnership requires nonzero new owner
        vm.assume(newOwner != address(0));

        // The deployer (this test contract) is the initial owner due to Ownable initializer in initialize
        // But our C was constructed via new C() and not initialized; however transferOwnership can still be called
        // only by owner — owner is the deployer (this contract). So call transferOwnership from this contract.

        // Call transferOwnership to set owner to fuzzed newOwner
        c.transferOwnership(newOwner);

        // The general invariant (the one-assertion): after setting owner to newOwner, c.owner() must equal newOwner.
        // This holds for the reference contract for all newOwner != address(0). The mutant flips nonzero _owner to address(0)
        // and thus will fail for any nonzero newOwner. We assert the property by reading the public owner() getter.
        assertTrue(c.owner() == newOwner);
    }
}

