contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz newOwner; for the correct contract any newOwner == address(0) causes revert and so owner() never becomes zero
    function testFuzz_property(address newOwner) public {
        // keep wide domain; allow any address
        // make caller the current owner (deployed contract's initialize not called so owner is address(0) initially due to initializer logic not run)
        // To ensure we are owner, we need to mimic ownership: call __Ownable_init by calling initialize. Provide dummy contracts for required params.

        // Deploy minimal dummy contracts to satisfy initialize signature
        DummyERC20 token = new DummyERC20();
        DummyERC20 usdc = new DummyERC20();
        DummyRewardRouter rr = new DummyRewardRouter();
        DummyGlpManager gm = new DummyGlpManager();

        // initialize expects an address for dnGmxJuniorVault and keeper; pass address(this) as vault and keeper
        c.initialize(token, usdc, rr, gm, address(this), address(this));

        // Now msg.sender must be owner to call transferOwnership; use vm.prank to act as owner
        address ownerBefore = c.owner();
        vm.prank(ownerBefore);

        bool ok;
        // call transferOwnership and catch reverts
        try c.transferOwnership(newOwner) { ok = true; } catch { ok = false; }

        // The universal property: after the call completes without revert (ok==true), owner() is never address(0) on the reference implementation.
        // For the correct contract this holds for all inputs because when newOwner==address(0) it reverts (ok==false), and when ok==true owner() == newOwner != address(0).
        // Mutant that removes the require will allow ok==true and owner()==address(0) when newOwner==address(0), violating this assertion.
        if (ok) {
            assertTrue(c.owner() != address(0));
        } else {
            // if call reverted, still the owner should not have become zero
            assertTrue(c.owner() != address(0));
        }
    }
}

