pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed parameters: ownerCaller will be the caller who is current owner, and newOwner is the target new owner
    function testFuzz_property(address ownerCaller, address newOwner) public {
        // keep addresses non-zero and distinct where needed; allow wide domain
        vm.assume(ownerCaller != address(0));
        vm.assume(newOwner != address(0));

        // ensure the contract is initialized so Ownable owner is set to deployer in initialize; but constructor of C doesn't initialize
        // We rely on transferOwnership being protected by onlyOwner so we must make ownerCaller the current owner.
        // The contract's owner is initially address(this) because setUp used new C() and __Ownable_init is not called in constructor;
        // To ensure owner is ownerCaller, we simulate by calling transferOwnership from the current owner (address(this)) to ownerCaller first.

        // First, get current owner (should be address(0) by default since __Ownable_init wasn't called in constructor),
        // but to be robust, attempt to transfer ownership from deployer (this) to ownerCaller using a direct call as this is the current owner.
        // We must call transferOwnership as the current owner (the test contract). Use vm.prank to simulate calls from this test contract isn't needed.

        // Note: Since setUp created c via new C(), the internal owner is likely address(0) until initialize is called; however transferOwnership has onlyOwner modifier which checks owner()==_msgSender().
        // To ensure we are owner, we first transfer ownership only if current owner equals address(this).

        address currentOwner = c.owner();

        // If currentOwner != address(this), try to become owner by calling initialize to set owner to msg.sender inside __Ownable_init via initializer.
        // We can call initialize from this test contract; initializer requires either top-level initializing or contract not a contract — but initializer allows when !_initializing and _initialized < 1 OR not contract and _initialized ==1; calling initialize should work here.
        // However rather than relying on initializer semantics, attempt to call transferOwnership only when this test is current owner. If not, we attempt to call a function that sets owner: call c.__GMXBatchingManager_init is internal so unavailable.
        // Simpler approach: if currentOwner != address(this), we skip the scenario because we cannot call transferOwnership as ownerCaller; require that currentOwner == address(this).

        vm.assume(currentOwner == address(this));

        // Now from this test contract (the current owner) transfer ownership to ownerCaller so owner becomes ownerCaller.
        c.transferOwnership(ownerCaller);
        // check that owner is ownerCaller now
        assertTrue(c.owner() == ownerCaller);

        // Now impersonate ownerCaller and call transferOwnership(newOwner)
        vm.prank(ownerCaller);
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: for any nonzero newOwner and valid caller (current owner), after calling transferOwnership(newOwner), owner() MUST equal newOwner.
        // This holds on the reference implementation for all inputs; the mutant that calls _transferOwnership(_msgSender()) instead of _transferOwnership(newOwner)
        // will cause owner() to remain equal to the caller (ownerCaller) rather than newOwner for many inputs, making this assert fail.
        assertTrue(c.owner() == newOwner);
    }
}

