        // current owner is this test contract. Transfer ownership to caller.
        c.transferOwnership(caller);

        // Now the caller should be owner. Prank as caller and call transferOwnership(newOwner).
        vm.prank(caller);
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
