            // or call reverted (ok==false) and owner is unchanged (still caller). This still distinguishes mutant because mutant will
            // succeed and set owner to caller, violating owner==newOwner for that successful case.
            // Implement single final assertion combining the cases.
            assertTrue(!ok ? (c.owner() == caller) : (c.owner() == newOwner));
        }
    }
