        // Determine expected value by trying to call a function that is only allowed whenNotPaused or whenPaused.
        // We can observe behavior: calling pauseDeposit when already paused reverts (onlyKeeper uses _pause modifier),
        // but easier: try to call unpauseDeposit as keeper; if it reverts with "Pausable: not paused" then contract is not paused.
        bool expectPaused;
        vm.prank(actor);
        try c.unpauseDeposit() {
            // unpause succeeded => it was paused before
            expectPaused = true;
            // restore paused state for consistency: pause again
            vm.prank(actor);
            c.pauseDeposit();
        } catch (bytes memory) {
            // unpause reverted => not paused
            expectPaused = false;
        }

        // The invariant: paused() must equal the actual paused status inferred above for ALL inputs on reference.
        // The buggy mutant returns false always, so when expectPaused == true the mutant will fail.
        assertTrue(pausedView == expectPaused);
    }
}

